    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">
    <link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet">
    <style>
        :root{--ink:#172033;--muted:#718096;--brand:#5b5bd6;--line:#e7eaf0;--canvas:#f5f7fb}
        *{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.topbar{background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:1020}.brand-mark{width:42px;height:42px;border-radius:13px;background:linear-gradient(135deg,var(--brand),#8b5cf6);display:grid;place-items:center;color:#fff}.page-shell{max-width:1500px;margin:auto;padding:30px 24px 50px}.eyebrow{color:var(--brand);font-size:.75rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.page-title{font-weight:750;letter-spacing:-.035em}.subtext{font-size:.78rem;color:var(--muted)}.soft-btn{border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:12px;padding:.65rem .9rem;font-weight:600}.summary-pill,.status-badge{display:inline-flex;align-items:center;gap:6px;border-radius:999px;font-weight:700}.summary-pill{padding:8px 12px;font-size:.8rem}.status-badge{padding:6px 10px;font-size:.73rem}.available{background:#e8f8f1;color:#087d55}.checked{background:#fff5dc;color:#a06600}.room-card{height:100%;background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 8px 28px rgba(32,41,64,.045);overflow:hidden;transition:.2s}.room-card:hover{transform:translateY(-2px);box-shadow:0 12px 32px rgba(32,41,64,.08)}.room-card.is-out{border-color:#f0cf85}.room-body{padding:20px}.holder{min-height:76px;background:#fafbfc;border:1px solid #eff1f5;border-radius:13px;padding:13px}.form-control,.form-select{border-color:var(--line);border-radius:11px;min-height:43px}.form-control:focus,.form-select:focus{border-color:#aaaaf1;box-shadow:0 0 0 .22rem #5b5bd615}.btn-brand{background:var(--brand);border-color:var(--brand);color:#fff}.btn-brand:hover{background:#4646b8;border-color:#4646b8;color:#fff}.history-link{color:var(--brand);font-size:.84rem;font-weight:700;text-decoration:none}.modal-content{border:0;border-radius:20px;box-shadow:0 30px 80px #17203333}.activity-drawer{width:min(620px,100vw)!important;border:0}.activity-drawer .offcanvas-header{padding:24px;border-bottom:1px solid var(--line);background:linear-gradient(135deg,#fafaff,#fff)}.activity-drawer .offcanvas-body{padding:24px;background:#f8f9fc}.audit-entry{position:relative;background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px;margin-bottom:16px;box-shadow:0 6px 20px rgba(32,41,64,.04)}.audit-entry:before{content:"";position:absolute;left:-7px;top:22px;width:13px;height:13px;border-radius:50%;background:var(--brand);border:3px solid #e7e7ff}.audit-meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.audit-detail{background:#f8f9fc;border-radius:10px;padding:10px}.audit-detail label{display:block;font-size:.67rem;font-weight:800;text-transform:uppercase;color:var(--muted);margin-bottom:3px}.audit-status{display:inline-flex;align-items:center;border-radius:999px;padding:6px 10px;font-size:.72rem;font-weight:750}.audit-returned{background:#e8f8f1;color:#087d55}.audit-out{background:#fff5dc;color:#a06600}@media(max-width:767px){.page-shell{padding:20px 12px}.top-actions .label{display:none}.audit-meta{grid-template-columns:1fr}}
    </style>
</head>
<body>
<header class="topbar"><div class="container-fluid px-3 px-md-4 py-3 d-flex align-items-center justify-content-between"><div class="d-flex align-items-center gap-3"><div class="brand-mark"><i class="bi bi-key-fill"></i></div><div><div class="fw-bold">SPC Admin</div><div class="subtext">Room key management</div></div></div><div class="d-flex gap-2 top-actions"><a href="{{ route('dashboard') }}" class="soft-btn text-decoration-none"><i class="bi bi-people me-md-2"></i><span class="label">Registrations</span></a><a href="{{ route('analytics') }}" class="soft-btn text-decoration-none"><i class="bi bi-bar-chart-line me-md-2"></i><span class="label">Analytics</span></a><form action="{{ route('logout') }}" method="POST">@csrf<button class="soft-btn text-danger"><i class="bi bi-box-arrow-right"></i></button></form></div></div></header>
<main class="page-shell">
    <div class="d-flex flex-column flex-md-row justify-content-between align-items-md-end gap-3 mb-4"><div><div class="eyebrow mb-2">Accommodation control</div><h1 class="page-title h2 mb-1">Room Key Register</h1><p class="text-secondary mb-0">Add every collection and return as a separate activity.</p></div><div id="room-summary" class="d-flex gap-2"><span class="summary-pill available"><i class="bi bi-check-circle-fill"></i>{{ $rooms->whereNull('activeKeyLog')->count() }} available</span><span class="summary-pill checked"><i class="bi bi-clock-fill"></i>{{ $rooms->whereNotNull('activeKeyLog')->count() }} out</span></div></div>
    <div id="ajax-message"></div>
    <div class="row g-4">
        @foreach($rooms as $room)
            @php($log = $room->activeKeyLog)
            <div id="room-card-{{ $room->id }}" class="col-12 col-md-6 col-xl-4"><article class="room-card {{ $log ? 'is-out' : '' }}"><div class="room-body">
                <div class="d-flex justify-content-between align-items-start mb-3"><div><h2 class="h5 fw-bold mb-1">{{ $room->name }}</h2><div class="subtext"><i class="bi bi-tag me-1"></i>{{ $room->key_label }}</div></div><span class="status-badge {{ $log ? 'checked' : 'available' }}">{{ $log ? 'Checked out' : 'Available' }}</span></div>
                <div class="holder mb-3">@if($log)<div class="subtext text-uppercase fw-bold mb-1">Currently with</div><div class="fw-bold">{{ $log->collector_name }}</div><a class="small text-decoration-none" href="tel:{{ $log->collector_phone }}">{{ $log->collector_phone }}</a>@else<div class="d-flex align-items-center h-100 text-secondary"><i class="bi bi-key me-2"></i>Key is ready for collection</div>@endif</div>
                <button type="button" class="btn btn-brand w-100 activity-button" data-room-name="{{ $room->name }}" data-checkout-url="{{ route('room-keys.checkout', $room) }}" data-return-url="{{ $log ? route('room-keys.return', $log) : '' }}" data-collector-name="{{ $log?->collector_name }}" data-collector-phone="{{ $log?->collector_phone }}" data-current-action="{{ $log ? 'returned' : 'collected' }}"><i class="bi bi-plus-circle me-2"></i>Add key activity</button>
                <button type="button" data-audit-url="{{ route('room-keys.history', $room) }}" class="history-link btn btn-link w-100 mt-2"><i class="bi bi-clock-history me-1"></i>View all activity</button>
            </div></article></div>
        @endforeach
    </div>
</main>

<div class="modal fade" id="activityModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="activityForm"><div class="modal-header px-4"><div><div class="eyebrow">New activity</div><h5 id="activityTitle" class="modal-title mt-1"></h5></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body px-4">
    <div class="mb-3"><label class="form-label fw-semibold">Activity type</label><select id="activityType" name="activity_type" class="form-select"><option value="collected">Key collected now</option><option value="returned">Key returned now</option><option value="completed">Manually log collected and returned</option></select><div id="activityHelp" class="form-text"></div></div>
    <div id="collectorFields"><div class="mb-3"><label class="form-label fw-semibold">Collector's full name</label><input name="collector_name" maxlength="255" class="form-control" placeholder="Enter full name"></div><div class="mb-3"><label class="form-label fw-semibold">Phone number</label><input name="collector_phone" type="tel" maxlength="30" class="form-control" placeholder="e.g. 0801 234 5678"></div><div><label class="form-label fw-semibold">Collection note <span class="text-secondary fw-normal">(optional)</span></label><textarea name="checkout_note" rows="2" maxlength="1000" class="form-control"></textarea></div></div>
    <div id="manualTimes" class="row g-3 mt-0 d-none"><div class="col-sm-6"><label class="form-label fw-semibold">Collected at</label><input name="collected_at" type="datetime-local" class="form-control"></div><div class="col-sm-6"><label class="form-label fw-semibold">Returned at</label><input name="returned_at" type="datetime-local" class="form-control"></div></div>
    <div id="returnerFields" class="d-none mt-3"><div class="form-check mb-3"><input id="sameReturner" name="same_returner" value="1" type="checkbox" class="form-check-input"><label for="sameReturner" class="form-check-label fw-semibold">Same person who collected the key returned it</label></div><div id="differentReturner" class="row g-3"><div class="col-sm-6"><label class="form-label fw-semibold">Returner's name</label><input name="returner_name" maxlength="255" class="form-control"></div><div class="col-sm-6"><label class="form-label fw-semibold">Returner's phone</label><input name="returner_phone" type="tel" maxlength="30" class="form-control"></div></div></div>
    <div id="returnFields" class="d-none mt-3"><label class="form-label fw-semibold">Return note <span class="text-secondary fw-normal">(optional)</span></label><textarea name="return_note" rows="3" maxlength="1000" class="form-control" placeholder="Key condition or handover note"></textarea></div>
    <div id="formError" class="alert alert-danger mt-3 mb-0 d-none"></div>
</div><div class="modal-footer px-4"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button id="saveActivity" class="btn btn-brand">Save activity</button></div></form></div></div></div>
<aside class="offcanvas offcanvas-end activity-drawer" tabindex="-1" id="auditDrawer"><div class="offcanvas-header"><div><div id="auditKey" class="eyebrow"></div><h4 id="auditTitle" class="offcanvas-title mt-1">Key activity</h4><p class="text-secondary small mb-0 mt-1">Complete collection and return history</p></div><button class="btn-close" data-bs-dismiss="offcanvas"></button></div><div id="auditBody" class="offcanvas-body"></div></aside>

<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
<script>
const csrf=document.querySelector('meta[name="csrf-token"]').content,activityModal=bootstrap.Modal.getOrCreateInstance('#activityModal'),activityForm=document.getElementById('activityForm');let selectedRoom;
const escapeHtml=value=>{const el=document.createElement('div');el.textContent=value??'';return el.innerHTML};
function configureForm(){const type=document.getElementById('activityType').value,needsCollector=type!=='returned',hasReturn=type!=='collected',isManual=type==='completed',same=document.getElementById('sameReturner').checked;document.getElementById('collectorFields').classList.toggle('d-none',!needsCollector);document.getElementById('returnFields').classList.toggle('d-none',!hasReturn);document.getElementById('returnerFields').classList.toggle('d-none',!hasReturn);document.getElementById('differentReturner').classList.toggle('d-none',same);document.getElementById('manualTimes').classList.toggle('d-none',!isManual);document.querySelector('[name="collector_name"]').required=needsCollector;document.querySelector('[name="collector_phone"]').required=needsCollector;document.querySelector('[name="returner_name"]').required=hasReturn&&!same;document.querySelector('[name="returner_phone"]').required=hasReturn&&!same;document.querySelector('[name="collected_at"]').required=isManual;document.querySelector('[name="returned_at"]').required=isManual;document.getElementById('activityHelp').textContent=type==='collected'?'Record who is taking the key.':isManual?'Enter an earlier collection and return from the manual register.':'Record who physically returned the key.'}
async function refreshRoom(id){const response=await fetch(@json(route('room-keys.index')),{headers:{'X-Requested-With':'XMLHttpRequest'}}),copy=new DOMParser().parseFromString(await response.text(),'text/html');document.getElementById(`room-card-${id}`).replaceWith(copy.getElementById(`room-card-${id}`));document.getElementById('room-summary').replaceWith(copy.getElementById('room-summary'))}
document.getElementById('activityType').addEventListener('change',configureForm);
document.getElementById('sameReturner').addEventListener('change',configureForm);
document.addEventListener('click',async event=>{const activityButton=event.target.closest('.activity-button');if(activityButton){selectedRoom=activityButton;activityForm.reset();document.getElementById('formError').classList.add('d-none');document.getElementById('activityTitle').textContent=activityButton.dataset.roomName;document.getElementById('activityType').value=activityButton.dataset.currentAction;document.querySelector('#activityType option[value="collected"]').disabled=Boolean(activityButton.dataset.returnUrl);document.querySelector('#activityType option[value="returned"]').disabled=!activityButton.dataset.returnUrl;document.querySelector('#activityType option[value="completed"]').disabled=Boolean(activityButton.dataset.returnUrl);configureForm();activityModal.show();return}const auditButton=event.target.closest('[data-audit-url]');if(!auditButton)return;const drawer=bootstrap.Offcanvas.getOrCreateInstance('#auditDrawer'),body=document.getElementById('auditBody');body.innerHTML='<div class="text-center py-5"><div class="spinner-border text-primary"></div></div>';drawer.show();try{const response=await fetch(auditButton.dataset.auditUrl,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}}),payload=await response.json();document.getElementById('auditKey').textContent=payload.room.key_label;document.getElementById('auditTitle').textContent=`${payload.room.name} Activity`;const rows=payload.logs.data;body.innerHTML=rows.length?rows.map(log=>`<article class="audit-entry"><div class="d-flex justify-content-between align-items-start gap-3"><div><div class="fw-bold fs-6">${escapeHtml(log.collector_name)}</div><a class="small text-decoration-none" href="tel:${escapeHtml(log.collector_phone)}"><i class="bi bi-telephone me-1"></i>${escapeHtml(log.collector_phone)}</a></div><span class="audit-status ${log.returned_at?'audit-returned':'audit-out'}"><i class="bi bi-${log.returned_at?'check-circle-fill':'clock-fill'} me-1"></i>${log.returned_at?'Returned':'With collector'}</span></div><div class="audit-meta"><div class="audit-detail"><label>Collected</label><div class="small">${escapeHtml(log.collected_at)}</div><div class="subtext">Recorded by ${escapeHtml(log.checked_out_by)}</div></div><div class="audit-detail"><label>Returned</label><div class="small">${escapeHtml(log.returned_at||'Not returned yet')}</div>${log.returner_name?`<div class="fw-semibold small mt-1">${escapeHtml(log.returner_name)}</div><div class="subtext">${escapeHtml(log.returner_phone||'No phone')} · recorded by ${escapeHtml(log.returned_by)}</div>`:''}</div></div>${log.checkout_note||log.return_note?`<div class="mt-3 pt-3 border-top small">${log.checkout_note?`<div><strong>Collection:</strong> ${escapeHtml(log.checkout_note)}</div>`:''}${log.return_note?`<div class="mt-1"><strong>Return:</strong> ${escapeHtml(log.return_note)}</div>`:''}</div>`:''}</article>`).join(''):'<div class="text-center text-secondary py-5"><i class="bi bi-inbox fs-2 d-block mb-2"></i>No activity recorded yet.</div>'}catch(error){body.innerHTML='<div class="alert alert-danger">Unable to load activity.</div>'}});
activityForm.addEventListener('submit',async event=>{event.preventDefault();const type=document.getElementById('activityType').value,url=type==='returned'?selectedRoom.dataset.returnUrl:selectedRoom.dataset.checkoutUrl,button=document.getElementById('saveActivity'),error=document.getElementById('formError');button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm me-2"></span>Saving…';error.classList.add('d-none');try{const data=new FormData(activityForm);if(type==='returned')data.append('_method','PATCH');const response=await fetch(url,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:data}),payload=await response.json();if(!response.ok)throw new Error(Object.values(payload.errors||{}).flat()[0]||payload.message||'Unable to save');activityModal.hide();await refreshRoom(payload.room_id);document.getElementById('ajax-message').innerHTML=`<div class="alert alert-success border-0 shadow-sm">${escapeHtml(payload.message)}</div>`}catch(exception){error.textContent=exception.message;error.classList.remove('d-none')}finally{button.disabled=false;button.textContent='Save activity'}});
</script>
</body></html>
